import React, { useState } from 'react';

import clsx from 'clsx';

import {
  firstDateOfMonth,
  getISODay,
  getWeekDay,
  lastDateOfMonth,
  weekCount,
} from '@helpers/dateHelper';

import styles from './styles.module.css';

interface IMonthHeader {
  title: string;
  weeksCount: number;
  isIntersectPrev: boolean;
}

interface IActivitiesChartProps {
  onDayClick: (d: Date) => void;
  dayContentMap?: { [isoDay: string]: React.ReactNode };
  d1: Date;
  d2: Date;
  zoom?: number;
}

const ActivitiesChart = ({
  d1,
  d2,
  dayContentMap,
  onDayClick,
  zoom = 12,
}: IActivitiesChartProps) => {
  const [size, setSize] = useState(zoom);

  const firstDay = React.useMemo(() => firstDateOfMonth(d1), [d1]);
  const lastDay = React.useMemo(() => lastDateOfMonth(d2), [d2]);

  const weekDayNames = React.useMemo(() => {
    const nearestMonday = new Date(new Date().getTime() - 86_400_000 * (new Date().getDay() - 1));
    return Array(7)
      .fill('E')
      .map((_, i) =>
        new Date(nearestMonday.getTime() + 86_400_000 * i).toLocaleDateString('default', {
          weekday: 'short',
        }),
      );
  }, []);

  const startMonthEmptyDays = React.useMemo(
    () => Array(getWeekDay(firstDay)).fill('E'),
    [firstDay],
  );

  const [allDates, monthsHeaders] = React.useMemo<[Date[], IMonthHeader[]]>(() => {
    const headers: Array<IMonthHeader> = [];
    const dates: Date[] = [];
    let currentTimestampMs = firstDay.getTime();

    while (currentTimestampMs <= lastDay.getTime()) {
      const currentDate = new Date(currentTimestampMs);
      const nextDayTimestampMs = currentTimestampMs + 86_400_000;

      if (currentDate.getMonth() !== new Date(nextDayTimestampMs).getMonth()) {
        const [month, year] = currentDate
          .toLocaleDateString('default', {
            month: 'short',
            year: '2-digit',
          })
          .split(/\s/);
        headers.push({
          weeksCount: weekCount(currentDate),
          isIntersectPrev: headers.length > 0 && firstDateOfMonth(currentDate).getDay() !== 1,
          title: `${month.replace('.', '').toUpperCase()}'${year}`,
        });
      }
      dates.push(currentDate);
      currentTimestampMs = nextDayTimestampMs;
    }
    return [dates, headers];
  }, [firstDay, lastDay]);

  const handleZoom = React.useCallback(
    (coeff: number) => async (e: React.MouseEvent) => {
      if (e.altKey || e.shiftKey) coeff *= -1;
      setSize((cu) => {
        const newVal = cu + coeff;
        if (newVal > 40) return cu;
        if (newVal < 11) return cu;
        return cu + coeff;
      });
    },
    [],
  );

  return (
    <div className={clsx('toolbared', styles.activityChart)} style={{ fontSize: size + 'px' }}>
      <div className={styles.weekDaysList}>
        <div className={clsx(styles.zoomControl, 'show-on-hover')}>
          <span onClick={handleZoom(2)} style={{ cursor: 'zoom-in' }}>
            +
          </span>
          /
          <span onClick={handleZoom(-2)} style={{ cursor: 'zoom-out' }}>
            -
          </span>
        </div>
        {weekDayNames.map((n) => {
          return (
            <div key={n} className={styles.weekDay}>
              <small>{n}</small>
            </div>
          );
        })}
      </div>
      <div className={styles.main}>
        <div className={styles.monthsBar}>
          {monthsHeaders.map((m) => (
            <div
              key={m.title}
              className={clsx(styles.monthTitle, m.isIntersectPrev && styles.monthIntersectLeft)}
              style={{ ['--count']: m.weeksCount } as React.CSSProperties}
            >
              <small>{m.title}</small>
            </div>
          ))}
        </div>
        <div className={styles.daysContainer}>
          {startMonthEmptyDays.map((_a, x) => (
            <div key={x} className={clsx(styles.empty_point, styles.day)} />
          ))}
          {allDates.map((x) => {
            const isoD = getISODay(x, false);
            return (
              <div
                title={isoD}
                className={clsx('bg-light', styles.day)}
                key={isoD}
                onClick={() => onDayClick(x)}
              >
                {dayContentMap?.[isoD] ? (
                  <span className={styles.dayContent}>{dayContentMap[isoD]}</span>
                ) : null}
                <strong className={clsx('text-muted', styles.dayNumber)}>{x.getDate()}</strong>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default ActivitiesChart;
